35	class SankeyPathShape {
36	    x1 = 0;
37	    y1 = 0;
38	
39	    x2 = 0;
40	    y2 = 0;
41	
42	    cpx1 = 0;
43	    cpy1 = 0;
44	
45	    cpx2 = 0;
46	    cpy2 = 0;
47	
48	    extent = 0;
49	    orient: LayoutOrient;
50	}
51	
52	interface SankeyPathProps extends PathProps {
53	    shape?: Partial<SankeyPathShape>
54	}
55	
56	class SankeyPath extends graphic.Path<SankeyPathProps> {
57	    shape: SankeyPathShape;
58	
59	    constructor(opts?: SankeyPathProps) {
60	        super(opts);
61	    }
62	
63	    getDefaultShape() {
64	        return new SankeyPathShape();
65	    }
66	
67	    buildPath(ctx: CanvasRenderingContext2D, shape: SankeyPathShape) {
68	        const extent = shape.extent;
69	        ctx.moveTo(shape.x1, shape.y1);
70	        ctx.bezierCurveTo(
71	            shape.cpx1, shape.cpy1,
72	            shape.cpx2, shape.cpy2,
73	            shape.x2, shape.y2
74	        );
75	        if (shape.orient === 'vertical') {
76	            ctx.lineTo(shape.x2 + extent, shape.y2);
77	            ctx.bezierCurveTo(
78	                shape.cpx2 + extent, shape.cpy2,
79	                shape.cpx1 + extent, shape.cpy1,
80	                shape.x1 + extent, shape.y1
81	            );
82	        }
83	        else {
84	            ctx.lineTo(shape.x2, shape.y2 + extent);
85	            ctx.bezierCurveTo(
86	                shape.cpx2, shape.cpy2 + extent,
87	                shape.cpx1, shape.cpy1 + extent,
88	                shape.x1, shape.y1 + extent
89	            );
90	        }
91	        ctx.closePath();
92	    }
93	
94	    highlight() {
95	        enterEmphasis(this);
96	    }
97	
98	    downplay() {
99	        leaveEmphasis(this);
100	    }
101	}
