103	class SankeyView extends ChartView {
104	
105	    static readonly type = 'sankey';
106	    readonly type = SankeyView.type;
107	
108	    private _model: SankeySeriesModel;
109	
110	    private _focusAdjacencyDisabled = false;
111	
112	    private _data: SeriesData;
113	
114	    render(seriesModel: SankeySeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
115	        const sankeyView = this;
116	        const graph = seriesModel.getGraph();
117	        const group = this.group;
118	        const layoutInfo = seriesModel.layoutInfo;
119	        // view width
120	        const width = layoutInfo.width;
121	        // view height
122	        const height = layoutInfo.height;
123	        const nodeData = seriesModel.getData();
124	        const edgeData = seriesModel.getData('edge');
125	        const orient = seriesModel.get('orient');
126	
127	        this._model = seriesModel;
128	
129	        group.removeAll();
130	
131	        group.x = layoutInfo.x;
132	        group.y = layoutInfo.y;
133	
134	        // generate a bezire Curve for each edge
135	        graph.eachEdge(function (edge) {
136	            const curve = new SankeyPath();
137	            const ecData = getECData(curve);
138	            ecData.dataIndex = edge.dataIndex;
139	            ecData.seriesIndex = seriesModel.seriesIndex;
140	            ecData.dataType = 'edge';
141	            const edgeModel = edge.getModel<SankeyEdgeItemOption>();
142	            const lineStyleModel = edgeModel.getModel('lineStyle');
143	            const curvature = lineStyleModel.get('curveness');
144	            const n1Layout = edge.node1.getLayout();
145	            const node1Model = edge.node1.getModel<SankeyNodeItemOption>();
146	            const dragX1 = node1Model.get('localX');
147	            const dragY1 = node1Model.get('localY');
148	            const n2Layout = edge.node2.getLayout();
149	            const node2Model = edge.node2.getModel<SankeyNodeItemOption>();
150	            const dragX2 = node2Model.get('localX');
151	            const dragY2 = node2Model.get('localY');
152	            const edgeLayout = edge.getLayout();
153	            let x1: number;
154	            let y1: number;
155	            let x2: number;
156	            let y2: number;
157	            let cpx1: number;
158	            let cpy1: number;
159	            let cpx2: number;
160	            let cpy2: number;
161	
162	            curve.shape.extent = Math.max(1, edgeLayout.dy);
163	            curve.shape.orient = orient;
164	
165	            if (orient === 'vertical') {
166	                x1 = (dragX1 != null ? dragX1 * width : n1Layout.x) + edgeLayout.sy;
167	                y1 = (dragY1 != null ? dragY1 * height : n1Layout.y) + n1Layout.dy;
168	                x2 = (dragX2 != null ? dragX2 * width : n2Layout.x) + edgeLayout.ty;
169	                y2 = dragY2 != null ? dragY2 * height : n2Layout.y;
170	                cpx1 = x1;
171	                cpy1 = y1 * (1 - curvature) + y2 * curvature;
172	                cpx2 = x2;
173	                cpy2 = y1 * curvature + y2 * (1 - curvature);
174	            }
175	            else {
176	                x1 = (dragX1 != null ? dragX1 * width : n1Layout.x) + n1Layout.dx;
177	                y1 = (dragY1 != null ? dragY1 * height : n1Layout.y) + edgeLayout.sy;
178	                x2 = dragX2 != null ? dragX2 * width : n2Layout.x;
179	                y2 = (dragY2 != null ? dragY2 * height : n2Layout.y) + edgeLayout.ty;
180	                cpx1 = x1 * (1 - curvature) + x2 * curvature;
181	                cpy1 = y1;
182	                cpx2 = x1 * curvature + x2 * (1 - curvature);
183	                cpy2 = y2;
184	            }
185	
186	            curve.setShape({
187	                x1: x1,
188	                y1: y1,
189	                x2: x2,
190	                y2: y2,
191	                cpx1: cpx1,
192	                cpy1: cpy1,
193	                cpx2: cpx2,
194	                cpy2: cpy2
195	            });
196	
197	            curve.useStyle(lineStyleModel.getItemStyle());
198	            // Special color, use source node color or target node color
199	            applyCurveStyle(curve.style, orient, edge);
200	
201	
202	            const defaultEdgeLabelText = `${edgeModel.get('value')}`;
203	            const edgeLabelStateModels = getLabelStatesModels(edgeModel, 'edgeLabel');
204	
205	            setLabelStyle(
206	                curve, edgeLabelStateModels,
207	                {
208	                    labelFetcher: {
209	                        getFormattedLabel(dataIndex, stateName, dataType, labelDimIndex, formatter, extendParams) {
210	                            return seriesModel.getFormattedLabel(
211	                                dataIndex, stateName, 'edge',
212	                                labelDimIndex,
213	                                // ensure edgeLabel formatter is provided
214	                                // to prevent the inheritance from `label.formatter` of the series
215	                                retrieve3(
216	                                    formatter,
217	                                    edgeLabelStateModels.normal && edgeLabelStateModels.normal.get('formatter'),
218	                                    defaultEdgeLabelText
219	                                ),
220	                                extendParams
221	                            );
222	                        }
223	                    },
224	                    labelDataIndex: edge.dataIndex,
225	                    defaultText: defaultEdgeLabelText
226	                }
227	            );
228	            curve.setTextConfig({ position: 'inside' });
229	
230	            const emphasisModel = edgeModel.getModel('emphasis');
231	
232	            setStatesStylesFromModel(curve, edgeModel, 'lineStyle', (model) => {
233	                const style = model.getItemStyle();
234	
235	                applyCurveStyle(style, orient, edge);
236	
237	                return style;
238	            });
239	
240	            group.add(curve);
241	
242	            edgeData.setItemGraphicEl(edge.dataIndex, curve);
243	
244	            const focus = emphasisModel.get('focus');
245	            toggleHoverEmphasis(
246	                curve,
247	                focus === 'adjacency' ? edge.getAdjacentDataIndices()
248	                : focus === 'trajectory' ? edge.getTrajectoryDataIndices()
249	                : focus,
250	                emphasisModel.get('blurScope'),
251	                emphasisModel.get('disabled')
252	            );
253	        });
254	
255	        // Generate a rect for each node
256	        graph.eachNode(function (node) {
257	            const layout = node.getLayout();
258	            const itemModel = node.getModel<SankeyNodeItemOption>();
259	            const dragX = itemModel.get('localX');
260	            const dragY = itemModel.get('localY');
261	            const emphasisModel = itemModel.getModel('emphasis');
262	
263	            const rect = new graphic.Rect({
264	                shape: {
265	                    x: dragX != null ? dragX * width : layout.x,
266	                    y: dragY != null ? dragY * height : layout.y,
267	                    width: layout.dx,
268	                    height: layout.dy
269	                },
270	                style: itemModel.getModel('itemStyle').getItemStyle(),
271	                z2: 10
272	            });
273	
274	            setLabelStyle(
275	                rect, getLabelStatesModels(itemModel),
276	                {
277	                    labelFetcher: {
278	                        getFormattedLabel(dataIndex, stateName) {
279	                            return seriesModel.getFormattedLabel(dataIndex, stateName, 'node');
280	                        }
281	                    },
282	                    labelDataIndex: node.dataIndex,
283	                    defaultText: node.id
284	                }
285	            );
286	
287	            (rect as ECElement).disableLabelAnimation = true;
288	
289	            rect.setStyle('fill', node.getVisual('color'));
290	            rect.setStyle('decal', node.getVisual('style').decal);
291	
292	            setStatesStylesFromModel(rect, itemModel);
293	
294	            group.add(rect);
295	
296	            nodeData.setItemGraphicEl(node.dataIndex, rect);
297	
298	            getECData(rect).dataType = 'node';
299	
300	            const focus = emphasisModel.get('focus');
301	            toggleHoverEmphasis(
302	                rect,
303	                focus === 'adjacency'
304	                    ? node.getAdjacentDataIndices()
305	                    : focus === 'trajectory'
306	                    ? node.getTrajectoryDataIndices()
307	                    : focus,
308	                emphasisModel.get('blurScope'),
309	                emphasisModel.get('disabled')
310	            );
311	        });
312	
313	        nodeData.eachItemGraphicEl(function (el: graphic.Rect, dataIndex: number) {
314	            const itemModel = nodeData.getItemModel<SankeyNodeItemOption>(dataIndex);
315	            if (itemModel.get('draggable')) {
316	                el.drift = function (this: typeof el, dx, dy) {
317	                    sankeyView._focusAdjacencyDisabled = true;
318	                    this.shape.x += dx;
319	                    this.shape.y += dy;
320	                    this.dirty();
321	                    api.dispatchAction({
322	                        type: 'dragNode',
323	                        seriesId: seriesModel.id,
324	                        dataIndex: nodeData.getRawIndex(dataIndex),
325	                        localX: this.shape.x / width,
326	                        localY: this.shape.y / height
327	                    });
328	                };
329	                el.ondragend = function () {
330	                    sankeyView._focusAdjacencyDisabled = false;
331	                };
332	                el.draggable = true;
333	                el.cursor = 'move';
334	            }
335	        });
336	
337	        if (!this._data && seriesModel.isAnimationEnabled()) {
338	            group.setClipPath(createGridClipShape(group.getBoundingRect(), seriesModel, function () {
339	                group.removeClipPath();
340	            }));
341	        }
342	
343	        this._data = seriesModel.getData();
344	    }
345	
346	    dispose() {
347	    }
348	}
349	
350	/**
351	 * Special color, use source node color or target node color
352	 * @param curveProps curve's style to parse
353	 * @param orient direction
354	 * @param edge current curve data
355	 */
356	function applyCurveStyle(curveProps: PathStyleProps, orient: 'horizontal' | 'vertical', edge: GraphEdge) {
357	    switch (curveProps.fill) {
358	        case 'source':
359	            curveProps.fill = edge.node1.getVisual('color');
360	            curveProps.decal = edge.node1.getVisual('style').decal;
361	            break;
362	        case 'target':
363	            curveProps.fill = edge.node2.getVisual('color');
364	            curveProps.decal = edge.node2.getVisual('style').decal;
365	            break;
366	        case 'gradient':
367	            const sourceColor = edge.node1.getVisual('color');
368	            const targetColor = edge.node2.getVisual('color');
369	            if (isString(sourceColor) && isString(targetColor)) {
370	                curveProps.fill = new graphic.LinearGradient(
371	                    0, 0, +(orient === 'horizontal'), +(orient === 'vertical'), [{
372	                        color: sourceColor,
373	                        offset: 0
374	                    }, {
375	                        color: targetColor,
376	                        offset: 1
377	                    }]
378	                );
379	            }
380	    }
381	}
382	
383	// Add animation to the view
384	function createGridClipShape(rect: RectLike, seriesModel: SankeySeriesModel, cb: () => void) {
385	    const rectEl = new graphic.Rect({
386	        shape: {
387	            x: rect.x - 10,
388	            y: rect.y - 10,
389	            width: 0,
390	            height: rect.height + 20
391	        }
392	    });
393	    graphic.initProps(rectEl, {
394	        shape: {
395	            width: rect.width + 20
396	        }
397	    }, seriesModel, cb);
398	
399	    return rectEl;
400	}
401	
402	export default SankeyView;

