147	class SankeySeriesModel extends SeriesModel<SankeySeriesOption> {
148	    static readonly type = 'series.sankey';
149	    readonly type = SankeySeriesModel.type;
150	
151	    levelModels: Model<SankeyLevelOption>[];
152	
153	    layoutInfo: LayoutRect;
154	
155	    /**
156	     * Init a graph data structure from data in option series
157	     */
158	    getInitialData(option: SankeySeriesOption, ecModel: GlobalModel) {
159	        const links = option.edges || option.links;
160	        const nodes = option.data || option.nodes;
161	        const levels = option.levels;
162	        this.levelModels = [];
163	        const levelModels = this.levelModels;
164	
165	        for (let i = 0; i < levels.length; i++) {
166	            if (levels[i].depth != null && levels[i].depth >= 0) {
167	                levelModels[levels[i].depth] = new Model(levels[i], this, ecModel);
168	            }
169	            else {
170	                if (__DEV__) {
171	                    throw new Error('levels[i].depth is mandatory and should be natural number');
172	                }
173	            }
174	        }
175	        if (nodes && links) {
176	            const graph = createGraphFromNodeEdge(nodes, links, this, true, beforeLink);
177	            return graph.data;
178	        }
179	        function beforeLink(nodeData: SeriesData, edgeData: SeriesData) {
180	            nodeData.wrapMethod('getItemModel', function (model: Model, idx: number) {
181	                const seriesModel = model.parentModel as SankeySeriesModel;
182	                const layout = seriesModel.getData().getItemLayout(idx);
183	                if (layout) {
184	                    const nodeDepth = layout.depth;
185	                    const levelModel = seriesModel.levelModels[nodeDepth];
186	                    if (levelModel) {
187	                        model.parentModel = levelModel;
188	                    }
189	                }
190	                return model;
191	            });
192	
193	            edgeData.wrapMethod('getItemModel', function (model: Model, idx: number) {
194	                const seriesModel = model.parentModel as SankeySeriesModel;
195	                const edge = seriesModel.getGraph().getEdgeByIndex(idx);
196	                const layout = edge.node1.getLayout();
197	                if (layout) {
198	                    const depth = layout.depth;
199	                    const levelModel = seriesModel.levelModels[depth];
200	                    if (levelModel) {
201	                        model.parentModel = levelModel;
202	                    }
203	                }
204	                return model;
205	            });
206	        }
207	    }
208	
209	    setNodePosition(dataIndex: number, localPosition: number[]) {
210	        const nodes = this.option.data || this.option.nodes;
211	        const dataItem = nodes[dataIndex];
212	        dataItem.localX = localPosition[0];
213	        dataItem.localY = localPosition[1];
214	    }
215	
216	    /**
217	     * Return the graphic data structure
218	     *
219	     * @return graphic data structure
220	     */
221	    getGraph() {
222	        return this.getData().graph;
223	    }
224	
225	    /**
226	     * Get edge data of graphic data structure
227	     *
228	     * @return data structure of list
229	     */
230	    getEdgeData() {
231	        return this.getGraph().edgeData;
232	    }
233	
234	    formatTooltip(
235	        dataIndex: number,
236	        multipleSeries: boolean,
237	        dataType: 'node' | 'edge'
238	    ) {
239	        function noValue(val: unknown): boolean {
240	            return isNaN(val as number) || val == null;
241	        }
242	        // dataType === 'node' or empty do not show tooltip by default
243	        if (dataType === 'edge') {
244	            const params = this.getDataParams(dataIndex, dataType);
245	            const rawDataOpt = params.data as SankeyEdgeItemOption;
246	            const edgeValue = params.value;
247	            const edgeName = rawDataOpt.source + ' -- ' + rawDataOpt.target;
248	            return createTooltipMarkup('nameValue', {
249	                name: edgeName,
250	                value: edgeValue,
251	                noValue: noValue(edgeValue)
252	            });
253	        }
254	        // dataType === 'node'
255	        else {
256	            const node = this.getGraph().getNodeByIndex(dataIndex);
257	            const value = node.getLayout().value;
258	            const name = (this.getDataParams(dataIndex, dataType).data as SankeyNodeItemOption).name;
259	            return createTooltipMarkup('nameValue', {
260	                name: name != null ? name + '' : null,
261	                value: value,
262	                noValue: noValue(value)
263	            });
264	        }
265	    }
266	
267	    optionUpdated() {}
268	
269	    // Override Series.getDataParams()
270	    getDataParams(dataIndex: number, dataType: 'node' | 'edge') {
271	        const params = super.getDataParams(dataIndex, dataType);
272	        if (params.value == null && dataType === 'node') {
273	            const node = this.getGraph().getNodeByIndex(dataIndex);
274	            const nodeValue = node.getLayout().value;
275	            params.value = nodeValue;
276	        }
277	        return params;
278	    }
