import { createChart, removeChart } from '../test/ut/core/utHelper';

// Safeguard for "feat(sankey): add `itemStyle.borderRadius` option for sankey series".
// Node rects should honor series-level (and data-level) itemStyle.borderRadius,
// while leaving it unset keeps sharp rectangular corners.
describe('sankey-border-radius', function () {

    function getNodeRadii(chart: ReturnType<typeof createChart>) {
        const series = chart.getModel().getSeriesByIndex(0) as any;
        const data = series.getData();
        const radii: Record<string, any> = {};
        data.each(function (idx: number) {
            const rect = data.getItemGraphicEl(idx) as any;
            radii[data.getName(idx)] = rect.shape.r;
        });
        return radii;
    }

    it('applies series-level itemStyle.borderRadius to node rects', function () {
        const chart = createChart();
        chart.setOption({
            series: [{
                type: 'sankey',
                itemStyle: {
                    borderRadius: 5
                },
                data: [{ name: 'a' }, { name: 'b' }],
                links: [{ source: 'a', target: 'b', value: 5 }]
            }]
        });
        const radii = getNodeRadii(chart);
        expect(radii.a).toBe(5);
        expect(radii.b).toBe(5);
        removeChart(chart);
    });

    it('supports array-valued and per-node borderRadius', function () {
        const chart = createChart();
        chart.setOption({
            series: [{
                type: 'sankey',
                data: [
                    { name: 'a', itemStyle: { borderRadius: [2, 4, 6, 8] } },
                    { name: 'b' }
                ],
                links: [{ source: 'a', target: 'b', value: 5 }]
            }]
        });
        const radii = getNodeRadii(chart);
        expect(radii.a).toEqual([2, 4, 6, 8]);
        removeChart(chart);
    });

    it('keeps sharp corners by default when borderRadius is unset', function () {
        const chart = createChart();
        chart.setOption({
            series: [{
                type: 'sankey',
                data: [{ name: 'a' }, { name: 'b' }],
                links: [{ source: 'a', target: 'b', value: 5 }]
            }]
        });
        const radii = getNodeRadii(chart);
        expect(radii.a).toBe(0);
        expect(radii.b).toBe(0);
        removeChart(chart);
    });
});
